describe('project deletion and status filtering', () => {
  it('deletes a project with 204, then its retrieval and repeated deletion are 404 problems', async () => {
    const project = await createProject();
    const deleted = await request(app).delete(`/v1/projects/${project.id}`);
    expect(deleted.status).toBe(204);
    expect(deleted.text).toBe('');
    expectProblem(await request(app).get(`/v1/projects/${project.id}`), 404);
    expectProblem(await request(app).delete(`/v1/projects/${project.id}`), 404);
  });

  it('returns 404 for an unknown id and 422 for a malformed id on delete', async () => {
    expectProblem(await request(app).delete(`/v1/projects/${UNKNOWN_ID}`), 404);
    expectProblem(await request(app).delete('/v1/projects/not-a-uuid'), 422);
  });

  it('filters by status and paginates the filtered set', async () => {
    const active = await Promise.all([createProject(), createProject(), createProject()]);
    const archived = await Promise.all([
      createProject({ status: 'archived' }),
      createProject({ status: 'archived' }),
      createProject({ status: 'archived' }),
    ]);
    const archivedIds = await listAll({ status: 'archived', limit: '1' });
    expect(archivedIds).toEqual(archived.map((project) => project.id));
    const activeIds = await listAll({ status: 'active', limit: '2' });
    expect(activeIds).toEqual(active.map((project) => project.id));
    const allIds = await listAll({ limit: '100' });
    expect(allIds).toEqual(expect.arrayContaining([...active, ...archived].map((project) => project.id)));
  });

  it('rejects an unknown status with a 422 problem', async () => {
    expectProblem(await request(app).get('/v1/projects').query({ status: 'pending' }), 422);
  });
});

